            type="number"
            value={autoplayInterval.toString()}
            onChange={(e, data) => {
              const value = parseInt(data.value, 10);
              if (!isNaN(value) && value >= 1000) {
                setAutoplayInterval(value);
              }
            }}
            min="1000"
            step="1000"
          />
        </Field>
