      <ToolbarToggleButton
        aria-label="Underline"
        icon={<TextUnderlineRegular />}
        name="textOptions"
        value="underline"
      />
    </Tooltip>
    <ToolbarDivider />
    <Tooltip content="Highlights the selected text" relationship="description" withArrow>
      <ToolbarButton aria-label="Highlight" icon={<HighlightFilled />} />
    </Tooltip>
  </Toolbar>
