            const { layout, ...itemProps } = item.getTreeItemProps();
            return item.itemType === 'leaf' ? (
              <SortableTreeItem key={item.value} {...itemProps}>
                <TreeItemLayout>{layout}</TreeItemLayout>
              </SortableTreeItem>
            ) : (
              <FlatTreeItem {...itemProps} key={item.value}>
                <TreeItemLayout>{layout}</TreeItemLayout>
              </FlatTreeItem>
            );
          })}
        </FlatTree>
      </SortableContext>
    </DndContext>
  );
};

